def lsub(s, prefix, new):
    out=[];hit=0
    for l in s.split('\n'):
        if l.startswith(prefix): out.append(new);hit+=1
        else: out.append(l)
    assert hit==1,(hit,prefix); return '\n'.join(out)
def rep(s,old,new):
    assert s.count(old)==1,(s.count(old),old[:70]); return s.replace(old,new)

